mapper.select:
SELECT * FROM CHALLENGE WHERE DELETE_YN = false
AND PROGRESS_STATUS = #{progressStatus}
ORDER BY CREATED_AT DESC

mapper.update:
UPDATE CHALLENGE
SET DELETE_YN = true
WHERE CODE = #{code}

UPDATE CHALLENGE
SET PROGRESS_STATUS =
		CASE
				WHEN END_DATE <= #{now} THEN 'ENDED'
				ELSE 'IN_PROGRESS'
		END

WHERE DELETE_YN = 0
	AND PROGRESS_STATUS IN ('WAITING', 'IN_PROGRESS')
	AND (
			END_DATE <= #{now}
			OR (
					PROGRESS_STATUS = 'WAITING'
					AND START_DATE <= #{now}
					AND END_DATE > #{now}
			)
	)

mapper.select:
SELECT POST_STATUS, PROGRESS_STATUS, START_DATE, END_DATE, DELETE_YN, MAX_PARTICIPANTS
FROM CHALLENGE WHERE CODE = #{code}
FOR UPDATE

SELECT EXISTS (
		SELECT 1
		FROM CHALLENGE_ENTRY
		WHERE CHAL_CODE = #{code}
			AND MEM_CODE = #{memCode}
)

SELECT EXISTS (
		SELECT 1
		FROM CHALLENGE_ENTRY
		WHERE CHAL_CODE = #{code}
			AND MEM_CODE = #{memCode}
			AND STATUS = 'JOINED'
			AND CANCELED_AT IS NULL
			AND DELETE_YN = 0
)
